using System;using System.IO;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;using System.Diagnostics;
namespace FleetLab {
 public sealed class StartupPage:UserControl {
  internal readonly ClipStudy Movie;internal readonly Button BackButton=new Button(),PauseButton=new Button(),SkipButton=new Button(),RestartButton=new Button();internal readonly StartupCanvas Canvas=new StartupCanvas();
  readonly Label note=new Label();readonly string assets;readonly Timer timer=new Timer();readonly Stopwatch clock=Stopwatch.StartNew();long last,elapsed;bool disposed;IndexedImage exit;Bitmap image;string problem="";
  internal bool HasOpened{get;private set;}internal bool Playing{get;private set;}internal int Stage{get;private set;}internal int Index{get;private set;}internal int Factor{get;private set;}internal Bitmap CurrentImage{get{return image;}}public event Action ReturnRequested;
  public StartupPage(string root):this(root,null){}
  internal StartupPage(string root,IClipOutput backend){assets=root;Dock=DockStyle.Fill;BackColor=Color.FromArgb(10,22,34);ForeColor=Color.WhiteSmoke;Movie=backend==null?new ClipStudy(root):new ClipStudy(root,backend);Movie.ConfigureStartup();
   var header=new TableLayoutPanel{Dock=DockStyle.Top,Height=112,ColumnCount=1,RowCount=3,Padding=new Padding(10,4,10,2)};foreach(int h in new[]{28,40,38})header.RowStyles.Add(new RowStyle(SizeType.Absolute,h));header.Controls.Add(new Label{Text="Original startup movies · P pauses · Space / left click skips a movie · Escape returns to title",Dock=DockStyle.Fill},0,0);note.Dock=DockStyle.Fill;header.Controls.Add(note,0,1);var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};header.Controls.Add(buttons,0,2);Add(buttons,BackButton,"Back to title",delegate{Back();});Add(buttons,PauseButton,"Pause",delegate{if(Playing)Pause();else Resume();});Add(buttons,SkipButton,"Skip movie (Space)",delegate{Skip();});Add(buttons,RestartButton,"Restart intro",delegate{Begin();});Canvas.Owner=this;Canvas.Dock=DockStyle.Fill;Canvas.AccessibleName="Original startup movie sequence";Controls.Add(Canvas);Controls.Add(header);timer.Interval=16;timer.Tick+=delegate{long now=clock.ElapsedMilliseconds,dt=now-last;last=now;if(Visible)Advance(dt);};timer.Start();Sync();
  }
  static void Add(Control parent,Button b,string text,EventHandler click){b.Text=text;b.AutoSize=true;b.Height=32;b.FlatStyle=FlatStyle.Flat;b.BackColor=Color.FromArgb(31,56,75);b.ForeColor=Color.WhiteSmoke;b.Click+=click;parent.Controls.Add(b);}
  internal void Begin(){if(disposed)return;Reset();StartupProgram.Read(File.ReadAllBytes(Path.Combine(Path.GetDirectoryName(assets),"Programs","Startup.seqbin")));HasOpened=Playing=true;Index=0;NextMovie();Canvas.Focus();}
  void NextMovie(){elapsed=0;exit=null;problem="";Factor=64;Stage=1;if(!Movie.LoadBattle(StartupProgram.Names[Index])){problem=Movie.Problem;Playing=false;}else Movie.ResumePlayback();last=clock.ElapsedMilliseconds;Render();Sync();}
  internal void Advance(long ms){if(disposed||!HasOpened||!Playing)return;if(ms<0)throw new ArgumentOutOfRangeException("ms");elapsed+=Math.Min(ms,500);
   if(Stage==1){while(elapsed>=50&&Stage==1){elapsed-=50;Movie.AdvanceCredits(50);if(Movie.Timeline.Completed)Fade(Movie.RawFrameCount-1);}Render();}
   else if(Stage==2){while(elapsed>=40&&Stage==2){elapsed-=40;if(Factor==0){Index++;if(Index>=StartupProgram.Names.Length){Stage=3;Playing=false;Replace(null);Sync();if(ReturnRequested!=null)ReturnRequested();return;}NextMovie();return;}Factor-=4;}Render();}Sync();
  }
  void Fade(int rawFrame){exit=Movie.IndexedFrame(rawFrame);Movie.UnloadBattle();Stage=2;Factor=64;elapsed=0;Render();Sync();}
  internal void Skip(){if(disposed||!HasOpened||Stage!=1||Movie.Timeline==null)return;int raw=Playing?CreditsPresentation.SkipFrame(Movie.Timeline.Frame,Movie.RawFrameCount):Movie.Timeline.Frame;Fade(raw);}
  internal void Back(){if(disposed||!HasOpened)return;Reset();if(ReturnRequested!=null)ReturnRequested();}
  internal bool Key(Keys key){if(!HasOpened||disposed)return false;if(key==Keys.P){if(Playing)Pause();else Resume();return true;}if(key==Keys.Space){Skip();return true;}if(key==Keys.Escape){Back();return true;}return false;}
  public void Pause(){if(disposed)return;Playing=false;Movie.Pause();Sync();}
  public void Resume(){if(disposed||!HasOpened||Stage==3||problem!="")return;Playing=true;last=clock.ElapsedMilliseconds;if(Stage==1)Movie.ResumePlayback();Sync();Canvas.Focus();}
  public void SetSound(bool enabled){if(disposed)return;Movie.SetSound(enabled);Sync();}public void SetLevel(int value){if(disposed)return;Movie.SetLevel(value);Sync();}
  internal void Reset(){if(disposed)return;HasOpened=Playing=false;Stage=0;Index=0;Factor=64;elapsed=0;exit=null;problem="";Movie.UnloadBattle();Replace(null);Sync();}
  void Render(){if(disposed||!HasOpened)return;IndexedImage raw=Stage==2?exit:Movie.Timeline==null?null:Movie.IndexedFrame(Movie.Timeline.Frame);if(raw==null){Replace(null);return;}var shown=new IndexedImage{Width=raw.Width,Height=raw.Height,Pixels=raw.Pixels,Palette=ClassicPalette.FadeDisplay(raw.Palette,Factor)};Replace(shown.Bitmap());}
  void Replace(Bitmap next){var previous=image;image=next;Canvas.Invalidate();if(previous!=null)previous.Dispose();}
  void Sync(){if(disposed)return;note.Text=HasOpened?"Intro "+(Index+1)+" / 3 · "+StartupProgram.Names[Math.Min(Index,2)]+(Stage==2?" · Fading":Playing?" · Playing":" · Paused")+(problem!=""?" · "+problem:Movie.Problem!=""?" · "+Movie.Problem:""):"Replay the three original startup movies";PauseButton.Text=Playing?"Pause":"Resume";PauseButton.Enabled=HasOpened&&Stage<3&&problem=="";SkipButton.Enabled=HasOpened&&Stage==1&&Movie.Timeline!=null;BackButton.Enabled=HasOpened;}
  protected override void Dispose(bool disposing){if(disposing&&!disposed){Reset();disposed=true;timer.Stop();timer.Dispose();Movie.Dispose();var old=image;image=null;if(old!=null)old.Dispose();}base.Dispose(disposing);}
  internal sealed class StartupCanvas:Control{internal StartupPage Owner;public StartupCanvas(){DoubleBuffered=true;ResizeRedraw=true;TabStop=true;BackColor=Color.Black;}protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button==MouseButtons.Left){Focus();Owner.Skip();}}protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Owner==null||Owner.image==null)return;float scale=Math.Min(Width/(float)Owner.image.Width,Height/(float)Owner.image.Height);var bounds=new RectangleF((Width-Owner.image.Width*scale)/2,(Height-Owner.image.Height*scale)/2,Owner.image.Width*scale,Owner.image.Height*scale);e.Graphics.InterpolationMode=InterpolationMode.NearestNeighbor;e.Graphics.PixelOffsetMode=PixelOffsetMode.Half;e.Graphics.DrawImage(Owner.image,bounds);}}
 }
}

